public class DateTimeFormatter_parseInto_TriageGen0Test {

    @Test(expected = IllegalArgumentException.class)
    public void parseInto_NullInstant_ThrowsException() {
        DateTimeFormatter formatter = new DateTimeFormatterBuilder().appendInstant().getFormatter();
        formatter.parseInto(null, "2023-01-01", 0);
    }

    @Test
    public void parseInto_SuccessfulParse_UpdatesInstant() {
        // Using a real formatter for functional correctness
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendOfYear()
                .appendLiteral('/')
                .appendMonthOfYear()
                .appendLiteral('/')
                .appendDayOfMonth()
                .getFormatter();

        // ReadWritableInstant is often implemented by MutableDateTime or similar in Joda
        // For testing purposes, we use a mock or a concrete implementation if available.
        // Since ReadWritableInstant is an interface, we mock it.
        ReadWritableInstant instant = mock(ReadWritableInstant.class);
        Chronology chronology = org.joda.time.thread.ThreadLocalChronology.getChronology();

        when(instant.getMillis()).thenReturn(0L);
        when(instant.getChronology()).thenReturn(chronology);
        when(chronology.getZone().getOffset(anyLong())).thenReturn(0);

        String text = "2023/01/01";
        int position = 0;

        int newPos = formatter.parseInto(instant, text, position);

        // Verify the parser moved the position
        // In "2023/01/01", after parsing year/month/day, the position should be at the end
        assertEquals(10, newPos);

        // Verify instant was updated
        verify(instant, atLeastOnce()).setMillis(anyLong());
        verify(instant, atLeastOnce()).setChronology(any(Chronology.class));
    }

    @Test
    public void parseInto_WithZoneParsed_UpdatesChronology() {
        // Formatter that parses an offset
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendOfYear()
                .appendLiteral('-')
                .appendMonthOfYear()
                .appendLiteral('-')
                .appendDayOfMonth()
                .appendLiteral(' ')
                .appendHourOfDay()
                .appendLiteral(':')
                .appendMinuteOfHour()
                .appendLiteral('+')
                .appendOffset("+HH:mm")
                .getFormatter();

        ReadWritableInstant instant = mock(ReadWritableInstant.class);
        Chronology chronology = org.joda.time.thread.ThreadLocalChronology.getChronology();

        when(instant.getMillis()).thenReturn(0L);
        when(instant.getChronology()).thenReturn(chronology);
        when(chronology.getZone().getOffset(anyLong())).thenReturn(0);

        String text = "2023-01-01 12:00+02:00";
        int newPos = formatter.parseInto(instant, text, 0);

        assertEquals(20, newPos);
        verify(instant).setChronology(argThat(c -> c.getZone().getOffset(0) != 0));
    }

