        when(chronology.getZone().getOffset(anyLong())).thenReturn(0);

        String text = "2023-01-01";
        formatter.parseInto(instant, text, 0);

        verify(instant, atLeastOnce()).setChronology(any(Chronology.class));
    }

    @Test
    public void parseInto_WithFixedZone_SetsZoneAtEnd() {
        // Test the branch: if (iZone != null) { instant.setZone(iZone); }
        DateTimeZone fixedZone = DateTimeZone.forID("UTC");
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendYear()
                .getFormatter()
                .withZone(fixedZone);

        ReadWritableInstant instant = mock(ReadWritableInstant.class);
        Chronology chronology = org.joda.time.thread.ThreadLocalChronology.getChronology();

        when(instant.getMillis()).thenReturn(0L);
        when(instant.getChronology()).thenReturn(chronology);
        when(chronology.getZone().getOffset(anyLong())).thenReturn(0);

        String text = "2023";
        formatter.parseInto(instant, text, 0);

        verify(instant).setZone(fixedZone);
    }

    @Test
    public void parseInto_WithPivotYear_Coverage() {
        // Test branch involving iPivotYear
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendYear()
                .getFormatter()
                .withPivotYear(2000);

        ReadWritableInstant instant = mock(ReadWritableInstant.class);
        Chronology chronology = org.joda.time.thread.ThreadLocalChronology.getChronology();

        when(instant.getMillis()).thenReturn(0L);
        when(instant.getChronology()).thenReturn(chronology);
        when(chronology.getZone().getOffset(anyLong())).thenReturn(0);

        String text = "2023";
        formatter.parseInto(instant, text, 0);

        // If no exception is thrown, the pivot year logic was exercised in the bucket constructor
    }
